1	package cli
2	
3	import (
4		"context"
5		"errors"
6		"os"
7		"os/exec"
8		"path/filepath"
9		"strings"
10		"testing"
11	)
12	
13	func newBatchTestRepo(t *testing.T, content string) (dir, spec string) {
14		t.Helper()
15		dir = t.TempDir()
16		run := func(args ...string) {
17			t.Helper()
18			cmd := exec.Command("git", args...)
19			cmd.Dir = dir
20			cmd.Env = append(os.Environ(),
21				"GIT_AUTHOR_NAME=t", "GIT_AUTHOR_EMAIL=t@t",
22				"GIT_COMMITTER_NAME=t", "GIT_COMMITTER_EMAIL=t@t",
23				"GIT_CONFIG_GLOBAL=/dev/null", "GIT_CONFIG_SYSTEM=/dev/null")
24			if out, err := cmd.CombinedOutput(); err != nil {
25				t.Fatalf("git %v: %v\n%s", args, err, out)
26			}
27		}
28		run("init", "-q", "-b", "main")
29		if err := os.WriteFile(filepath.Join(dir, "blob.txt"), []byte(content), 0o600); err != nil {
30			t.Fatal(err)
31		}
32		run("add", "blob.txt")
33		run("commit", "-q", "-m", "one")
34		return dir, "HEAD:blob.txt"
35	}
36	
37	func TestCatFileBatchReadReturnsBlobContent(t *testing.T) {
38		content := strings.Repeat("transcript line\n", 200)
39		dir, spec := newBatchTestRepo(t, content)
40		for range 3 { // repeated reads reuse one child and stay in sync
41			got, err := catFileBatchRead(context.Background(), dir, spec, true)
42			if err != nil {
43				t.Fatal(err)
44			}
45			if string(got) != content {
46				t.Fatalf("content mismatch: got %d bytes, want %d", len(got), len(content))
47			}
48		}
49	}
50	
51	func TestCatFileBatchMissingIsDefinitiveAndNonFatal(t *testing.T) {
52		dir, spec := newBatchTestRepo(t, "hello\n")
53		_, err := catFileBatchRead(context.Background(), dir, "HEAD:absent.txt", true)
54		if !errors.Is(err, errCatFileBatchMissing) {
55			t.Fatalf("want errCatFileBatchMissing, got %v", err)
56		}
57		// The child must survive a missing answer and serve the next read.
58		got, err := catFileBatchRead(context.Background(), dir, spec, true)
59		if err != nil || string(got) != "hello\n" {
60			t.Fatalf("read after missing: %q %v", got, err)
61		}
62	}
63	
64	func TestCatFileBatchRespawnsAfterChildDies(t *testing.T) {
65		dir, spec := newBatchTestRepo(t, "respawn\n")
66		ctx := context.Background()
67		if _, err := catFileBatchRead(ctx, dir, spec, true); err != nil {
68			t.Fatal(err)
69		}
70		key := catFileBatchKey{gitDir: dir, localOnly: true}
71		catFileBatchMu.Lock()
72		p := catFileBatchProcs[key]
73		catFileBatchMu.Unlock()
74		if p == nil {
75			t.Fatal("expected a registered batch child")
76		}
77		p.fail()
78		catFileBatchDrop(key, p)
79		got, err := catFileBatchRead(ctx, dir, spec, true)
80		if err != nil || string(got) != "respawn\n" {
81			t.Fatalf("read after kill: %q %v", got, err)
82		}
83	}
84	
85	func TestLocalObjectTypeBatchAndFallbackAgree(t *testing.T) {
86		dir, spec := newBatchTestRepo(t, "typed\n")
87		ctx := context.Background()
88		batched, err := localObjectType(ctx, ExecRunner{}, dir, spec)
89		if err != nil {
90			t.Fatal(err)
91		}
92		if batched != "blob" {
93			t.Fatalf("want blob, got %q", batched)
94		}
95		if _, err := localObjectType(ctx, ExecRunner{}, dir, "HEAD:absent.txt"); !errors.Is(err, errCatFileBatchMissing) {
96			t.Fatalf("want errCatFileBatchMissing, got %v", err)
97		}
98	}
99	
100	func TestCatFileWithPolicyMatchesPerExec(t *testing.T) {
101		content := "policy parity\n"
102		dir, _ := newBatchTestRepo(t, content)
103		ctx := context.Background()
104		for _, localOnly := range []bool{true, false} {
105			got, err := catFileWithPolicy(ctx, ExecRunner{}, dir, "HEAD", "blob.txt", localOnly)
106			if err != nil {
107				t.Fatalf("localOnly=%v: %v", localOnly, err)
108			}
109			if string(got) != content {
110				t.Fatalf("localOnly=%v: got %q", localOnly, got)
111			}
112		}
113		if _, err := catFileWithPolicy(ctx, ExecRunner{}, dir, "HEAD", "absent.txt", true); err == nil {
114			t.Fatal("want error for a missing path")
115		}
116	}
117	
118	func TestCatFileBatchRejectsNewlineSpec(t *testing.T) {
119		dir, _ := newBatchTestRepo(t, "x\n")
120		if _, err := catFileBatchRead(context.Background(), dir, "HEAD:a\nHEAD:b", true); err == nil {
121			t.Fatal("want error for a spec containing a newline")
122		}
123	}
